#include <iostream>

using namespace std;

int main() {
    int N;
    cin >> N;

    int TakahashiScore = 0; // チーム高橋の合計得点
    int AokiScore = 0; // チーム青木の合計得点
    for (int i = 0; i < N; ++i) {
        int X, Y;
        cin >> X >> Y;

        // それぞれのチームに得点をプラスする
        TakahashiScore += X;
        AokiScore += Y;
    }

    // 合計得点の大小に従って結果を出力
    if (TakahashiScore > AokiScore)
        cout << "Takahashi" << endl;
    else if (TakahashiScore > AokiScore)
        cout << "Aoki" << endl;
    else
        cout << "Draw" << endl;

    return 0;
}
